package com.yuegang.zhihui.order.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.mq.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;@Configuration(proxyBeanMethods=false)@ConditionalOnProperty(name="ygh.mq.enabled",havingValue="true")class OrderOutboxConfiguration{@Bean(destroyMethod="close")DomainEventPublisher orderEventPublisher(@Value("${ygh.mq.nameserver}")String n,@Value("${ygh.mq.topic:YGH_DOMAIN_EVENTS}")String t){return new RocketMqDomainEventPublisher("ygh-order-producer",n,t);}@Bean(destroyMethod="close")OrderWalletEventConsumer orderWalletEventConsumer(@Value("${ygh.mq.nameserver}")String n,@Value("${ygh.mq.topic:YGH_DOMAIN_EVENTS}")String t,OrderService s,ObjectMapper o){return new OrderWalletEventConsumer(n,t,s,o);}@Bean OrderOutboxJob orderOutboxJob(JdbcTemplate j,DomainEventPublisher p){return new OrderOutboxJob(new JdbcOutboxDispatcher(j,p,"order_outbox"));}static final class OrderOutboxJob{private final JdbcOutboxDispatcher d;OrderOutboxJob(JdbcOutboxDispatcher d){this.d=d;}@Scheduled(fixedDelayString="${ygh.mq.dispatch-delay:1000}")public void dispatch(){d.dispatch();}}}
